bloom-filter.pseudocode:
class BloomFilter:
    def __init__(self, m, hashes):
        self.bits = [0] * m  # m비트 배열
        self.hashes = hashes  # k개 해시 함수

    def add(self, x):
        for h in self.hashes:
            self.bits[h(x) % len(self.bits)] = 1

    def might_contain(self, x):
        # 하나라도 0이면 확실히 없음(거짓 음성 없음)
        # 모두 1이면 '아마 있음'(거짓 양성 가능)
        return all(self.bits[h(x) % len(self.bits)]
                   for h in self.hashes)

# 최적 해시 수 k = (m / n) * ln 2
